        0x52, 0x09, 0xd6, 0x90, 0xc0, 0x18, 0x8f, 0x20, 0x36, 0x53, 0x14, 0x80, 0xbc, 0xd8, 0x25, 0xe6,
        0x74, 0x0c, 0x11, 0x14, 0xf5,
    };
};

// ── mock transport (never touches the network) ──────────────────────────────

const MockTransport = struct {
    status: u16 = 200,
    body: []const u8 = &.{},
    calls: usize = 0,
    // `req.url` (esp. the GET-form URL) is a transient buffer owned and freed
    // by `Cache.refresh` right after the synchronous `fetch` call returns —
    // real production transports (e.g. `httpTransport`) only need it live for
    // the call itself. To inspect it *after* `refresh` returns, the mock must
    // take its own copy here rather than alias the caller's slice.
    last_url_owned: ?[]u8 = null,
    last_method: ocspcache.FetchMethod = .post,

    fn fetch(context: *anyopaque, gpa: std.mem.Allocator, req: ocspcache.FetchRequest) ocspcache.FetchError!ocspcache.FetchResponse {
        const self: *MockTransport = @ptrCast(@alignCast(context));
        self.calls += 1;
        if (self.last_url_owned) |u| gpa.free(u);
        self.last_url_owned = try gpa.dupe(u8, req.url);
        self.last_method = req.method;
        return .{ .status = self.status, .body = try gpa.dupe(u8, self.body) };
    }

    fn lastUrl(self: *const MockTransport) []const u8 {
        return self.last_url_owned orelse &.{};
    }

    fn deinit(self: *MockTransport, gpa: std.mem.Allocator) void {
        if (self.last_url_owned) |u| gpa.free(u);
    }

    fn transport(self: *MockTransport) ocspcache.Transport {
        return .{ .context = self, .fetchFn = fetch };
    }
};

