test "discoverResponderUrl: AIA-bearing certificate resolves the OCSP responder URL" {
    const url = (try ocspcache.discoverResponderUrl(subject_with_aia)).?;
    try testing.expectEqualStrings(responder_url, url);
}

test "discoverResponderUrl: certificate without AIA returns null, not an error" {
    try testing.expect((try ocspcache.discoverResponderUrl(subject_no_aia)) == null);
    // The issuer cert (plain rsa.selfSignedCert output) has no AIA either.
    try testing.expect((try ocspcache.discoverResponderUrl(issuer_der)) == null);
}

// ════════════════════════════════════════════════════════════════════════════
// Cache: fetch + verify-before-cache + serve
// ════════════════════════════════════════════════════════════════════════════

test "Cache.refresh: fetches, verifies and caches a good response; getStapled serves it" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200, .body = good_response };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{ .refresh_margin_seconds = margin });
    defer cache.deinit();

    const now = this_update_unix + 100;
    try cache.refresh(subject_with_aia, issuer_der, now);

    try testing.expectEqual(@as(usize, 1), mock.calls);
    try testing.expectEqualStrings(responder_url, mock.lastUrl());
    try testing.expectEqual(ocspcache.FetchMethod.post, mock.last_method);

    const staple = cache.getStapled(subject_with_aia, now).?;
    try testing.expectEqualSlices(u8, good_response, staple);
}

test "Cache.needsRefresh/getStapled: refresh-margin proactive flip vs actual nextUpdate expiry" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200, .body = good_response };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{ .refresh_margin_seconds = margin });
    defer cache.deinit();

    // No entry yet: always needs a refresh.
    try testing.expect(cache.needsRefresh(subject_with_aia, this_update_unix));

    try cache.refresh(subject_with_aia, issuer_der, this_update_unix + 100);

    // Fresh: well before nextUpdate - margin.
    try testing.expect(!cache.needsRefresh(subject_with_aia, this_update_unix + 100));

    // Past the refresh-margin threshold, but still before the actual
    // nextUpdate: proactively wants a refresh, but the cached response is
    // still genuinely valid and still served.
    try testing.expect(cache.needsRefresh(subject_with_aia, threshold_unix + 1));
    try testing.expect(cache.getStapled(subject_with_aia, threshold_unix + 1) != null);

    // Past the actual nextUpdate: no longer fresh enough to serve at all.
    try testing.expect(cache.needsRefresh(subject_with_aia, next_update_unix + 1));
    try testing.expect(cache.getStapled(subject_with_aia, next_update_unix + 1) == null);

    // Exactly AT nextUpdate: the doc contract is "expired iff now_unix >
    // nextUpdate" (strict), so the response is still servable at the exact
    // boundary instant — only the instant AFTER it is too late.
    try testing.expect(cache.getStapled(subject_with_aia, next_update_unix) != null);
}

test "Cache.refresh: tampered response fails verification and is never cached" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200, .body = tampered_response };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{});
    defer cache.deinit();

    const now = this_update_unix + 100;
    try testing.expectError(error.VerifyFailed, cache.refresh(subject_with_aia, issuer_der, now));
    try testing.expect(cache.getStapled(subject_with_aia, now) == null);
}

test "Cache.refresh: tryLater responder response is soft-failed; prior cache entry keeps serving" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200, .body = good_response };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{});
    defer cache.deinit();

    try cache.refresh(subject_with_aia, issuer_der, this_update_unix + 100);
    const before = cache.getStapled(subject_with_aia, this_update_unix + 100).?;
    const before_copy = try gpa.dupe(u8, before);
    defer gpa.free(before_copy);

    // OCSPResponse { responseStatus tryLater } — no responseBytes at all.
    mock.body = &[_]u8{ 0x30, 0x03, 0x0a, 0x01, 0x03 };
    try testing.expectError(error.ResponderUnsuccessful, cache.refresh(subject_with_aia, issuer_der, this_update_unix + 200));

    const after = cache.getStapled(subject_with_aia, this_update_unix + 200).?;
    try testing.expectEqualSlices(u8, before_copy, after);
}

test "Cache.refresh: responder HTTP error status is soft-failed; nothing cached on first attempt" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 503, .body = &.{} };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{});
    defer cache.deinit();

    const now = this_update_unix + 100;
    try testing.expectError(error.ResponderHttpError, cache.refresh(subject_with_aia, issuer_der, now));
    try testing.expect(cache.getStapled(subject_with_aia, now) == null);
}

test "Cache.refresh: re-refreshing an already-cached subject frees the old entry (no leak)" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200, .body = good_response };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{});
    defer cache.deinit();

    // First refresh: creates the entry.
    try cache.refresh(subject_with_aia, issuer_der, this_update_unix + 100);
    try testing.expectEqual(@as(usize, 1), cache.entries.count());

    // Second successful refresh of the SAME subject: `getOrPut` finds the
    // existing slot, so the old `response_der` allocation must be freed
    // before it is overwritten — otherwise `testing.allocator` flags a leak
    // at `cache.deinit()` below (this test's whole point).
    mock.body = good_response;
    try cache.refresh(subject_with_aia, issuer_der, this_update_unix + 200);
    try testing.expectEqual(@as(usize, 1), cache.entries.count());
    try testing.expect(cache.getStapled(subject_with_aia, this_update_unix + 200) != null);
}

test "Cache.refresh: subject certificate without AIA -> NoResponderUrl, nothing cached" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200, .body = good_response2 };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{});
    defer cache.deinit();

    const now = this_update_unix + 100;
    try testing.expectError(error.NoResponderUrl, cache.refresh(subject_no_aia, issuer_der, now));
    try testing.expectEqual(@as(usize, 0), mock.calls); // never even reached the transport
    try testing.expect(cache.getStapled(subject_no_aia, now) == null);
}

test "Cache.refresh: GET form builds the base64 URL and never sends a body" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200, .body = good_response };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{ .fetch_method = .get });
    defer cache.deinit();

    try cache.refresh(subject_with_aia, issuer_der, this_update_unix + 100);
    try testing.expectEqual(ocspcache.FetchMethod.get, mock.last_method);
    try testing.expect(std.mem.startsWith(u8, mock.lastUrl(), responder_url));
    try testing.expect(mock.lastUrl().len > responder_url.len);
}

test "Cache.refresh: Config.max_entries bounds distinct cached certificates" {
    const gpa = testing.allocator;

    var mock: MockTransport = .{ .status = 200 };
    defer mock.deinit(gpa);
    var cache = ocspcache.Cache.init(gpa, mock.transport(), .{ .max_entries = 1 });
    defer cache.deinit();

    const now = this_update_unix + 100;
    mock.body = good_response;
    try cache.refresh(subject_with_aia, issuer_der, now);

    mock.body = good_response3;
    try testing.expectError(error.CacheFull, cache.refresh(subject_with_aia2, issuer_der, now));

    // The first cert's entry is untouched.
    try testing.expect(cache.getStapled(subject_with_aia, now) != null);
    try testing.expect(cache.getStapled(subject_with_aia2, now) == null);
}

test "buildRequest smoke: Cache.refresh actually builds a well-formed OCSPRequest (ocsp module cross-check)" {
    const gpa = testing.allocator;
    const req = try ocsp.buildRequest(gpa, subject_with_aia, issuer_der, .{});
    defer gpa.free(req);
    // A structurally valid OCSPRequest at minimum parses as a SEQUENCE.
    try testing.expect(req.len > 2);
    try testing.expectEqual(@as(u8, 0x30), req[0]);
}
